CREATE EXTENSION pg_visibility;
CREATE EXTENSION pageinspect;

CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id int           NOT NULL,
    amount      numeric(10,2) NOT NULL,
    created_at  timestamptz   NOT NULL DEFAULT now()
);

INSERT INTO orders (customer_id, amount)
SELECT (random() * 999)::int + 1,
       round((random() * 5000)::numeric, 2)
  FROM generate_series(1, 100000);

VACUUM (VERBOSE) orders;

SELECT relfrozenxid, age(relfrozenxid) AS xid_age,
       relpages, relallvisible, relallfrozen
  FROM pg_class
 WHERE relname = 'orders';

VACUUM (FREEZE, VERBOSE) orders;

SELECT relfrozenxid, age(relfrozenxid) AS xid_age,
       relpages, relallvisible, relallfrozen
  FROM pg_class
 WHERE relname = 'orders';

SELECT * FROM pg_visibility_map_summary('orders');

ALTER TABLE orders SET (autovacuum_freeze_max_age = 100000,
                        log_autovacuum_min_duration = 0);

CREATE PROCEDURE burn_xids(n int)
LANGUAGE plpgsql AS $$
BEGIN
  FOR i IN 1..n LOOP
    PERFORM pg_current_xact_id();  -- assigns a new transaction ID
    COMMIT;                        -- ends it, so the next loop gets a new one
  END LOOP;
END $$;

CALL burn_xids(110000);

SELECT age(relfrozenxid) AS xid_age
  FROM pg_class
 WHERE relname = 'orders';

